function v2Permissions(){return head('Role capabilities','Admin inherits every CPO capability and adds platform scope.')+`<div class="scope-explainer">${icon('shield')}<div><strong>Same operational actions. Wider Admin scope.</strong><p>Admin actions retain the staff identity and target organisation. This demo checks scope locally; production must enforce the same rule on every server request.</p></div></div><section class="panel">${table(['Capability','CPO','Straumvakt Admin'],[['Read operational data','Own organisation','Every organisation'],['Create / edit sites, installations and chargers','Own organisation','Every organisation'],['Onboard / edit drivers and approve / revoke access','Own organisation','Every organisation'],['Create / edit access groups and schedules','Own organisation','Every organisation'],['Draft / edit / activate / terminate contract records','Own organisation','Every organisation'],['Draft / schedule tariffs and assign sites','Own organisation','Every organisation'],['Review CDRs, export and close billing periods','Own organisation','Every organisation'],['Manage team members and organisation settings','Own organisation','Every organisation'],['Investigate incidents and request remote operations','Own organisation','Every organisation'],['View / export reports and inspect audit history','Own organisation','Every organisation'],['Create / edit / suspend organisations','—','Platform'],['Platform subscription billing and capability model','—','Platform']])}</section>`;}
